package com.varlamoredistraction;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class VarlamoreDistractionPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(VarlamoreDistractionPlugin.class);
		RuneLite.main(args);
	}
}

