package com.varlamoredistraction;

import java.util.List;
import java.util.OptionalInt;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DistractionTrackerTest
{
	private static final long T0 = 1_600_000_000_000L;

	/**
	 * The shipped defaults: distraction runs to 24, white to 69, orange to 89, red to 99, dropped
	 * after 120.
	 */
	private static final DistractionTracker.Thresholds DEFAULTS =
		new DistractionTracker.Thresholds(24, 70, 90, 99, 120);

	private final DistractionTracker tracker = new DistractionTracker();

	private static long at(int seconds)
	{
		return T0 + seconds * 1000L;
	}

	private DistractionState stateAt(int seconds)
	{
		final WorldTimer row = tracker.forWorld(302, at(seconds), DEFAULTS);
		return row == null ? null : row.getState();
	}

	// --- colour band boundaries -------------------------------------------------------------

	@Test
	public void bandsFollowTheConfiguredBoundaries()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);

		assertEquals(DistractionState.ACTIVE, stateAt(0));
		assertEquals(DistractionState.ACTIVE, stateAt(23));
		assertEquals(DistractionState.FRESH, stateAt(24));
		assertEquals(DistractionState.FRESH, stateAt(69));
		assertEquals(DistractionState.APPROACHING, stateAt(70));
		assertEquals(DistractionState.APPROACHING, stateAt(89));
		assertEquals(DistractionState.IMMINENT, stateAt(90));
		assertEquals(DistractionState.IMMINENT, stateAt(99));
		assertEquals(DistractionState.MISSED, stateAt(100));
	}

	@Test
	public void elapsedKeepsCountingPastTheMissedThreshold()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);

		// The panel freezes the *display* at "99+"; the underlying count has to keep running so
		// pruning still knows when the row turns 120.
		assertEquals(110L, tracker.forWorld(302, at(110), DEFAULTS).getElapsedSeconds());
	}

	@Test
	public void subSecondElapsedReadsAsZeroRatherThanRoundingUp()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);
		assertEquals(0L, tracker.forWorld(302, T0 + 999, DEFAULTS).getElapsedSeconds());
	}

	// --- retention --------------------------------------------------------------------------

	@Test
	public void rowSurvivesToRetentionAndIsDroppedAfterIt()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);

		tracker.prune(at(120), DEFAULTS);
		assertEquals(1, tracker.size());

		tracker.prune(at(121), DEFAULTS);
		assertEquals(0, tracker.size());
		assertNull(tracker.forWorld(302, at(121), DEFAULTS));
	}

	@Test
	public void snapshotPrunesSoTheMapCannotGrowWithoutBound()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);
		assertTrue(tracker.snapshot(at(200), DEFAULTS).isEmpty());
		assertEquals(0, tracker.size());
	}

	// --- merge precedence within one distraction ---------------------------------------------

	@Test
	public void exactObservationOverwritesAnApproximateOne()
	{
		tracker.record(302, T0, DistractionSource.APPROXIMATE_LOCAL);
		tracker.record(302, at(5), DistractionSource.EXACT_LOCAL);

		final WorldTimer row = tracker.forWorld(302, at(5), DEFAULTS);
		assertEquals(DistractionSource.EXACT_LOCAL, row.getSource());
		assertEquals(0L, row.getElapsedSeconds());
	}

	@Test
	public void approximateObservationNeverOverwritesAnExactOne()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);
		tracker.record(302, at(5), DistractionSource.APPROXIMATE_LOCAL);

		final WorldTimer row = tracker.forWorld(302, at(5), DEFAULTS);
		assertEquals(DistractionSource.EXACT_LOCAL, row.getSource());
		assertEquals(5L, row.getElapsedSeconds());
		assertFalse(row.isApproximate());
	}

	@Test
	public void theEarliestReadingOfOneDistractionWins()
	{
		// Observed in game: all three urchins fire together and the chat line lands a tick or two
		// before a citizen's interacting flag, so the same distraction is reported several times.
		// Taking the later reading would drag the stamp forward and shorten every measured cycle.
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);
		assertFalse(tracker.record(302, at(2), DistractionSource.EXACT_LOCAL));

		assertEquals(2L, tracker.forWorld(302, at(2), DEFAULTS).getElapsedSeconds());
	}

	@Test
	public void aDuplicateReadingReportsThatItChangedNothing()
	{
		assertTrue(tracker.record(302, T0, DistractionSource.EXACT_LOCAL));
		assertFalse(tracker.record(302, T0, DistractionSource.EXACT_LOCAL));
	}

	@Test
	public void anEarlierReadingOfTheSameDistractionCorrectsALaterOne()
	{
		// Order is not guaranteed - the npc flag can be processed before the chat line.
		tracker.record(302, at(2), DistractionSource.EXACT_LOCAL);
		assertTrue(tracker.record(302, T0, DistractionSource.EXACT_LOCAL));

		assertEquals(2L, tracker.forWorld(302, at(2), DEFAULTS).getElapsedSeconds());
	}

	@Test
	public void anEndDerivedEstimateBeatsAMidFlightOneOnMeritNotTiming()
	{
		// The end-derived stamp is always the earlier of the two by construction, so "earliest
		// wins" would pick it regardless of whether it deserved to. Feed it in as the *later*
		// stamp to prove the tier is doing the work.
		tracker.record(302, T0, DistractionSource.APPROXIMATE_LOCAL);
		assertTrue(tracker.record(302, at(4), DistractionSource.ESTIMATED_FROM_END));

		assertEquals(DistractionSource.ESTIMATED_FROM_END,
			tracker.forWorld(302, at(4), DEFAULTS).getSource());
	}

	@Test
	public void aMidFlightEstimateNeverDisplacesAnEndDerivedOne()
	{
		tracker.record(302, at(4), DistractionSource.ESTIMATED_FROM_END);
		assertFalse(tracker.record(302, T0, DistractionSource.APPROXIMATE_LOCAL));
	}

	@Test
	public void bothEstimateTiersRenderAsApproximate()
	{
		tracker.record(301, T0, DistractionSource.ESTIMATED_FROM_END);
		tracker.record(302, T0, DistractionSource.APPROXIMATE_LOCAL);

		for (int world : new int[]{301, 302})
		{
			final WorldTimer row = tracker.forWorld(world, T0, DEFAULTS);
			assertTrue(row.isApproximate());
		}
	}

	@Test
	public void anExactReadingStillBeatsAnEndDerivedEstimate()
	{
		tracker.record(302, T0, DistractionSource.ESTIMATED_FROM_END);
		assertTrue(tracker.record(302, at(3), DistractionSource.EXACT_LOCAL));

		assertEquals(DistractionSource.EXACT_LOCAL, tracker.forWorld(302, at(3), DEFAULTS).getSource());
	}

	// --- merge across cycles ------------------------------------------------------------------

	@Test
	public void aLaterCycleWinsRegardlessOfSource()
	{
		// A second reading 90s later sits far past the same-cycle window, so it must describe
		// the next cycle - and the newer stamp wins even though its source is less trusted.
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);
		tracker.record(302, at(90), DistractionSource.ESTIMATED_FROM_END);

		final WorldTimer row = tracker.forWorld(302, at(90), DEFAULTS);
		assertEquals(DistractionSource.ESTIMATED_FROM_END, row.getSource());
		assertEquals(0L, row.getElapsedSeconds());
	}

	@Test
	public void twoEstimatesOfOneDistractionStayOneDistraction()
	{
		// Estimates of a single distraction can sit up to ~24s apart, since an inferred start
		// lands anywhere in [start-12, start+12]. They must not be read as two cycles.
		tracker.record(302, T0, DistractionSource.APPROXIMATE_LOCAL);
		assertFalse(tracker.record(302, at(24), DistractionSource.APPROXIMATE_LOCAL));

		assertEquals(24L, tracker.forWorld(302, at(24), DEFAULTS).getElapsedSeconds());
	}

	@Test
	public void aGenuinelyNewCycleIsNotMisfiledAsADuplicate()
	{
		// The regression this threshold exists for. Consecutive distractions are >= 84s apart, but
		// two estimates of them can be as little as 84-12-12 = 60s apart. Judging that against the
		// 84s event floor rejected the new cycle and left the world stale for a full rotation.
		tracker.record(302, T0, DistractionSource.APPROXIMATE_LOCAL);
		assertTrue(tracker.record(302, at(60), DistractionSource.APPROXIMATE_LOCAL));

		assertEquals(0L, tracker.forWorld(302, at(60), DEFAULTS).getElapsedSeconds());
	}

	@Test
	public void theSameCycleWindowSitsBetweenTheTwoPopulations()
	{
		// Sanity check on the derivation rather than the code: the threshold has to separate a
		// maximum same-cycle spread of ~24s from a minimum cross-cycle gap of ~60s.
		assertTrue(DistractionTracker.SAME_CYCLE_SECONDS > 24);
		assertTrue(DistractionTracker.SAME_CYCLE_SECONDS < DistractionTracker.MIN_INTERVAL_SECONDS - 24);
	}

	@Test
	public void aStaleReportOfAnEarlierCycleIsIgnored()
	{
		tracker.record(302, at(90), DistractionSource.EXACT_LOCAL);
		tracker.record(302, T0, DistractionSource.ESTIMATED_FROM_END);

		assertEquals(0L, tracker.forWorld(302, at(90), DEFAULTS).getElapsedSeconds());
	}

	@Test
	public void theActiveBandTracksTheConfiguredDistractionLength()
	{
		// The active window is the one boundary the game fixes, so it moves with the configured
		// duration rather than sitting at a threshold of its own.
		final DistractionTracker.Thresholds shortRun =
			new DistractionTracker.Thresholds(10, 70, 90, 99, 120);

		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);

		assertEquals(DistractionState.ACTIVE, tracker.forWorld(302, at(9), shortRun).getState());
		assertEquals(DistractionState.FRESH, tracker.forWorld(302, at(10), shortRun).getState());
	}

	@Test
	public void anActiveWorldStillSortsBelowOneCloserToFiring()
	{
		tracker.record(301, T0, DistractionSource.EXACT_LOCAL);          // active, 0s
		tracker.record(302, at(-80), DistractionSource.EXACT_LOCAL);     // approaching, 80s

		final List<WorldTimer> rows = tracker.snapshot(T0, DEFAULTS);
		assertEquals(302, rows.get(0).getWorld());
		assertEquals(DistractionState.ACTIVE, rows.get(1).getState());
	}

	@Test
	public void reobservingAWorldResetsItsTimer()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);
		tracker.record(302, at(91), DistractionSource.EXACT_LOCAL);

		assertEquals(0L, tracker.forWorld(302, at(91), DEFAULTS).getElapsedSeconds());
		// A world just re-observed is mid-distraction, not merely fresh.
		assertEquals(DistractionState.ACTIVE, stateAt(91));
	}

	// --- ordering ------------------------------------------------------------------------------

	@Test
	public void rowsSortMostUrgentFirstWithMissedWorldsLast()
	{
		tracker.record(301, at(-10), DistractionSource.EXACT_LOCAL);   // 10s elapsed at t=0
		tracker.record(302, at(-80), DistractionSource.EXACT_LOCAL);   // 80s elapsed
		tracker.record(303, at(-105), DistractionSource.EXACT_LOCAL);  // 105s elapsed -> MISSED
		tracker.record(304, at(-45), DistractionSource.EXACT_LOCAL);   // 45s elapsed

		final List<WorldTimer> rows = tracker.snapshot(T0, DEFAULTS);

		assertEquals(4, rows.size());
		assertEquals(302, rows.get(0).getWorld());
		assertEquals(304, rows.get(1).getWorld());
		assertEquals(301, rows.get(2).getWorld());
		assertEquals(303, rows.get(3).getWorld());
		assertEquals(DistractionState.MISSED, rows.get(3).getState());
	}

	@Test
	public void bestTargetSkipsMissedWorlds()
	{
		tracker.record(303, at(-105), DistractionSource.EXACT_LOCAL);
		tracker.record(302, at(-80), DistractionSource.EXACT_LOCAL);

		assertEquals(OptionalInt.of(302), tracker.bestTarget(T0, DEFAULTS));
	}

	@Test
	public void bestTargetIsEmptyWhenEveryWorldHasBeenMissed()
	{
		tracker.record(303, at(-105), DistractionSource.EXACT_LOCAL);

		assertEquals(OptionalInt.empty(), tracker.bestTarget(T0, DEFAULTS));
	}

	@Test
	public void clearDropsEverything()
	{
		tracker.record(302, T0, DistractionSource.EXACT_LOCAL);
		tracker.clear();
		assertEquals(0, tracker.size());
	}
}

