package com.varlamoredistraction;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Every string here was copied out of a real client log on 2026-08-15, colour tags included.
 */
public class ChatParsingTest
{
	@Test
	public void theDistractionMessageIsRecognised()
	{
		assertTrue(VarlamoreDistractionPlugin.isDistractionMessage(
			"You notice an urchin distract a wealthy citizen nearby."));
	}

	@Test
	public void colourTagsDoNotDefeatMatching()
	{
		assertTrue(VarlamoreDistractionPlugin.isLateArrivalMessage(
			"<col=ff3045>Your hands are sweaty and keep dropping the items in the Citizen's pockets."));
	}

	@Test
	public void theVerySweatyVariantIsRecognised()
	{
		// Regression: the wiki only documents "hands are sweaty", so the original matcher looked
		// for exactly that and silently missed this wording, seen in game on world 491.
		assertTrue(VarlamoreDistractionPlugin.isLateArrivalMessage(
			"<col=ff3045>Your hands are very sweaty and keep dropping the items in the Citizen's pockets."));
	}

	@Test
	public void bothWordingsAgreeWithEachOther()
	{
		final String plain = "Your hands are sweaty and keep dropping the items in the Citizen's pockets.";
		final String intensified = "Your hands are very sweaty and keep dropping the items in the Citizen's pockets.";

		assertTrue(VarlamoreDistractionPlugin.isLateArrivalMessage(plain));
		assertTrue(VarlamoreDistractionPlugin.isLateArrivalMessage(intensified));
	}

	@Test
	public void theTwoMessagesNeverMatchEachOther()
	{
		final String start = "You notice an urchin distract a wealthy citizen nearby.";
		final String late = "Your hands are sweaty and keep dropping the items in the Citizen's pockets.";

		assertFalse(VarlamoreDistractionPlugin.isLateArrivalMessage(start));
		assertFalse(VarlamoreDistractionPlugin.isDistractionMessage(late));
	}

	@Test
	public void unrelatedMessagesAreIgnored()
	{
		for (String message : new String[]{
			"You pick the citizen's pocket.",
			"You fail to pick the citizen's pocket.",
			"Your hands are cold.",
			"",
		})
		{
			assertFalse(message, VarlamoreDistractionPlugin.isDistractionMessage(message));
			assertFalse(message, VarlamoreDistractionPlugin.isLateArrivalMessage(message));
		}
	}

	@Test
	public void nonBreakingSpacesAreNormalised()
	{
		assertTrue(VarlamoreDistractionPlugin.isDistractionMessage(
			"You notice an urchin distract a\u00A0wealthy citizen nearby."));
	}
}

