package com.varlamoredistraction;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar. One row per tracked world, most urgent at the top.
 * <p>
 * Rows are only rebuilt when the ordering changes; otherwise the existing labels are updated in
 * place. At a 500ms refresh a full rebuild every tick would flicker and would fight the user's mouse
 * for hit targets.
 */
class VarlamoreDistractionPanel extends PluginPanel
{
	private final VarlamoreDistractionConfig config;

	private final JPanel rowContainer = new JPanel();
	private final JLabel emptyLabel = new JLabel();
	private final JLabel hintLabel = new JLabel();

	private final Map<Integer, WorldRow> rowsByWorld = new HashMap<>();
	private List<Integer> lastOrder = new ArrayList<>();

	VarlamoreDistractionPanel(VarlamoreDistractionConfig config)
	{
		super(false);

		this.config = config;

		setLayout(new BorderLayout(0, 6));
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JLabel title = new JLabel("Time since distraction");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);

		rowContainer.setLayout(new BoxLayout(rowContainer, BoxLayout.Y_AXIS));
		rowContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyLabel.setText("<html>No worlds tracked yet.<br>Stand in the bazaar until an urchin "
			+ "distracts a citizen.</html>");

		hintLabel.setFont(FontManager.getRunescapeSmallFont());
		hintLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		final JPanel south = new JPanel(new BorderLayout());
		south.setBackground(ColorScheme.DARK_GRAY_COLOR);
		south.add(emptyLabel, BorderLayout.NORTH);
		south.add(hintLabel, BorderLayout.SOUTH);

		add(title, BorderLayout.NORTH);
		add(rowContainer, BorderLayout.CENTER);
		add(south, BorderLayout.SOUTH);
	}

	/**
	 * Called on the Swing thread with an immutable snapshot taken elsewhere - the panel never reads
	 * plugin state itself.
	 */
	void update(List<WorldTimer> allRows, int currentWorld)
	{
		final List<WorldTimer> rows = currentFirst(allRows, currentWorld);

		final List<Integer> order = new ArrayList<>(rows.size());
		for (WorldTimer row : rows)
		{
			order.add(row.getWorld());
		}

		if (!order.equals(lastOrder))
		{
			rebuild(rows);
			lastOrder = order;
		}

		for (WorldTimer row : rows)
		{
			final WorldRow component = rowsByWorld.get(row.getWorld());
			if (component != null)
			{
				component.update(row, row.getWorld() == currentWorld);
			}
		}

		emptyLabel.setVisible(rows.isEmpty());
		hintLabel.setText(hintText());

		revalidate();
		repaint();
	}

	/**
	 * The world you are standing on is pinned to the top regardless of urgency - it is the one row
	 * you look at without hunting for it, and a row that reorders itself under the cursor is a row
	 * you misclick. Everything else keeps the tracker's most-urgent-first order.
	 * <p>
	 * Done here rather than in {@link DistractionTracker} on purpose: which world you are on is a
	 * display concern, and pushing it into the tracker would mean handing it the client's state and
	 * losing the property that makes the tracker testable.
	 */
	private static List<WorldTimer> currentFirst(List<WorldTimer> rows, int currentWorld)
	{
		final List<WorldTimer> ordered = new ArrayList<>(rows.size());
		for (WorldTimer row : rows)
		{
			if (row.getWorld() == currentWorld)
			{
				ordered.add(row);
			}
		}

		for (WorldTimer row : rows)
		{
			if (row.getWorld() != currentWorld)
			{
				ordered.add(row);
			}
		}

		return ordered;
	}

	private String hintText()
	{
		return "<html><br>Hop to the top world before it reaches "
			+ config.approachingAt() + "s.</html>";
	}

	private void rebuild(List<WorldTimer> rows)
	{
		rowContainer.removeAll();
		rowsByWorld.clear();

		for (WorldTimer row : rows)
		{
			final WorldRow component = new WorldRow();
			rowsByWorld.put(row.getWorld(), component);
			rowContainer.add(component);
		}
	}

	/** One world line: number on the left, elapsed time on the right. */
	private final class WorldRow extends JPanel
	{
		private final JLabel worldLabel = new JLabel();
		private final JLabel timeLabel = new JLabel();
		private boolean current;

		private WorldRow()
		{
			// BorderLayout rather than a two-column grid: "W302 (current)" is much wider than "45s",
			// and an even split clips it.
			setLayout(new BorderLayout(4, 0));
			setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createEmptyBorder(0, 0, 3, 0),
				new EmptyBorder(4, 6, 4, 6)));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

			worldLabel.setFont(FontManager.getRunescapeSmallFont());
			timeLabel.setFont(FontManager.getRunescapeSmallFont());
			timeLabel.setHorizontalAlignment(SwingConstants.RIGHT);

			add(worldLabel, BorderLayout.WEST);
			add(timeLabel, BorderLayout.EAST);
		}

		private Color restingBackground()
		{
			return current ? ColorScheme.DARK_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR;
		}

		private void update(WorldTimer row, boolean isCurrent)
		{
			if (current != isCurrent)
			{
				current = isCurrent;
				setBackground(restingBackground());
			}

			final String name = "W" + row.getWorld()
				+ (isCurrent ? " (current)" : "");
			worldLabel.setText(name);
			worldLabel.setForeground(isCurrent ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
			worldLabel.setFont(isCurrent
				? FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD)
				: FontManager.getRunescapeSmallFont());

			timeLabel.setText(VarlamoreDistractionPlugin.formatElapsed(row, config));
			timeLabel.setForeground(VarlamoreDistractionPlugin.colourFor(row.getState(), config));

			setToolTipText(tooltip(row, isCurrent));
		}

		private String tooltip(WorldTimer row, boolean isCurrent)
		{
			final StringBuilder sb = new StringBuilder("<html>World ").append(row.getWorld());
			if (isCurrent)
			{
				sb.append(" (you are here)");
			}
			if (row.isApproximate())
			{
				sb.append("<br>Estimated - not seen from the start");
			}
			if (row.getState() == DistractionState.MISSED)
			{
				sb.append("<br>Fired unseen; return and wait to re-time it");
			}
			return sb.append("</html>").toString();
		}
	}
}

