import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.OptionalInt;
import javax.annotation.Nullable;
import lombok.AllArgsConstructor;

/**
 * Per-world distraction timestamps, and every rule for interpreting them.
 * <p>
 * This class deliberately has no RuneLite imports and never reads the clock itself - callers pass
 * {@code nowMillis} in. That keeps the whole of the plugin's actual behaviour testable with plain
 * JUnit and no mocked client, and leaves the plugin class as a thin adapter that only translates
 * game events into {@link #record} calls.
 * <p>
 * Not thread safe. All access happens from the client thread or from the Swing thread via the
 * plugin's refresh task, never both at once.
 */
class DistractionTracker
{
	/**
	 * The game's own guarantee: consecutive distractions on one world are never closer together
	 * than this. Two readings less than this far apart therefore describe the same distraction
	 * measured twice, which is what lets {@link #record} tell "better reading" from "next cycle".
	 */
	static final int MIN_INTERVAL_SECONDS = 84;

	/**
	 * How far apart two stamps must be before they describe different distractions rather than one
	 * distraction measured twice.
	 * <p>
	 * This is deliberately not {@link #MIN_INTERVAL_SECONDS}. That is the floor on the interval
	 * between real <em>events</em>; this is a threshold on the difference between our <em>stamps</em>,
	 * which carry estimate error. An inferred start lands anywhere in {@code [start-12, start+12]},
	 * so:
	 * <ul>
	 *   <li>two readings of one distraction differ by at most about 24s, and</li>
	 *   <li>two readings of consecutive distractions differ by at least {@code 84 - 12 - 12 = 60s}.</li>
	 * </ul>
	 * Any value in that gap separates the two cases; 40 is the midpoint. Using 84 put the threshold
	 * outside the gap entirely, which misfiled a new cycle as a duplicate whenever the previous
	 * stamp ran late - observed in game on 2026-08-15, where two readings of one distraction landed
	 * either side of the 84s line and were classified differently.
	 */
	static final int SAME_CYCLE_SECONDS = 40;

	private final Map<Integer, Observation> byWorld = new HashMap<>();

	/**
	 * Record a distraction on a world. Returns true if this actually changed what we hold.
	 * <p>
	 * The merge rule leans on the 84 second floor above. If the incoming stamp is at least one
	 * minimum interval away from what we already hold, it must belong to a later cycle, so the
	 * newer stamp wins outright however precise the older reading was. Otherwise both stamps
	 * describe the same distraction, and the more precise source wins.
	 */
	boolean record(int world, long stampMillis, DistractionSource source)
	{
		final Observation incoming = new Observation(stampMillis, source);
		final Observation existing = byWorld.get(world);

		if (existing == null || supersedes(incoming, existing))
		{
			byWorld.put(world, incoming);
			return true;
		}

		return false;
	}

	private static boolean supersedes(Observation incoming, Observation existing)
	{
		final long deltaSeconds = Math.abs(incoming.stampMillis - existing.stampMillis) / 1000L;

		if (deltaSeconds >= SAME_CYCLE_SECONDS)
		{
			// Different cycles. Whichever is more recent describes the world as it stands now.
			return incoming.stampMillis > existing.stampMillis;
		}

		if (incoming.source.getPrecedence() != existing.source.getPrecedence())
		{
			return incoming.source.getPrecedence() < existing.source.getPrecedence();
		}

		// Same distraction, equally trusted sources: keep the earliest reading. Every detector can
		// only fire at or after the instant the distraction actually began, so the error is one
		// sided and the minimum is the least lagged estimate. Observed in game - all three urchins
		// fire together, and a citizen's interacting state registers a couple of ticks after the
		// chat message, so taking the newer reading would drag the stamp forward every cycle.
		return incoming.stampMillis < existing.stampMillis;
	}

	/**
	 * Every tracked world as sortable rows, most urgent first. Drops anything past the retention
	 * window as a side effect, so the map cannot grow without bound.
	 */
	List<WorldTimer> snapshot(long nowMillis, Thresholds thresholds)
	{
		prune(nowMillis, thresholds);

		final List<WorldTimer> rows = new ArrayList<>(byWorld.size());
		for (Map.Entry<Integer, Observation> entry : byWorld.entrySet())
		{
			final long elapsed = elapsedSeconds(entry.getValue(), nowMillis);
			rows.add(new WorldTimer(
				entry.getKey(),
				elapsed,
				thresholds.classify(elapsed),
				entry.getValue().source));
		}

		rows.sort(ROW_ORDER);
		return rows;
	}

	/**
	 * The world closest to firing that has not already fired unseen, or empty if nothing is live.
	 * This is what the overlay names as the hop target.
	 */
	OptionalInt bestTarget(long nowMillis, Thresholds thresholds)
	{
		for (WorldTimer row : snapshot(nowMillis, thresholds))
		{
			if (row.getState() != DistractionState.MISSED)
			{
				return OptionalInt.of(row.getWorld());
			}
		}
		return OptionalInt.empty();
	}

	@Nullable
	WorldTimer forWorld(int world, long nowMillis, Thresholds thresholds)
	{
		final Observation observation = byWorld.get(world);
		if (observation == null)
		{
			return null;
		}

		final long elapsed = elapsedSeconds(observation, nowMillis);
		return new WorldTimer(world, elapsed, thresholds.classify(elapsed), observation.source);
	}

	void prune(long nowMillis, Thresholds thresholds)
	{
		final Iterator<Map.Entry<Integer, Observation>> it = byWorld.entrySet().iterator();
		while (it.hasNext())
		{
			if (elapsedSeconds(it.next().getValue(), nowMillis) > thresholds.retentionSeconds)
			{
				it.remove();
			}
		}
	}

	void clear()
	{
		byWorld.clear();
	}

	int size()
	{
		return byWorld.size();
	}

	private static long elapsedSeconds(Observation observation, long nowMillis)
	{
		// Clamped so a stamp from a slightly fast clock reads as 0 rather than counting backwards.
		return Math.max(0L, (nowMillis - observation.stampMillis) / 1000L);
	}

	/**
	 * Most urgent first: live worlds ahead of missed ones, then longest elapsed, then the more
	 * precise reading, then world number so the order never jitters between refreshes.
	 */
	private static final Comparator<WorldTimer> ROW_ORDER =
		Comparator.comparing((WorldTimer r) -> r.getState() == DistractionState.MISSED)
			.thenComparing(Comparator.comparingLong(WorldTimer::getElapsedSeconds).reversed())
			.thenComparingInt(r -> r.getSource().getPrecedence())
			.thenComparingInt(WorldTimer::getWorld);

	@AllArgsConstructor
	private static final class Observation
	{
		private final long stampMillis;
		private final DistractionSource source;
	}

	/**
	 * The user's colour band boundaries, in seconds elapsed. Passed in from config rather than read
	 * here so this class stays free of RuneLite types.
	 */
	@AllArgsConstructor
	static final class Thresholds
	{
		/** How long a distraction runs. Below this the distraction is still active. */
		private final int activeUntil;
		private final int approachingAt;
		private final int imminentAt;
		private final int missedAt;
		private final int retentionSeconds;

		DistractionState classify(long elapsedSeconds)
		{
			if (elapsedSeconds < activeUntil)
			{
				return DistractionState.ACTIVE;
			}
			if (elapsedSeconds < approachingAt)
			{
				return DistractionState.FRESH;
			}
			if (elapsedSeconds < imminentAt)
			{
				return DistractionState.APPROACHING;
			}
			if (elapsedSeconds <= missedAt)
			{
				return DistractionState.IMMINENT;
			}
			return DistractionState.MISSED;
		}

		int getMissedAt()
		{
			return missedAt;
		}
	}
}

