)
public class VarlamoreDistractionPlugin extends Plugin
{
	/**
	 * Printed on the tick a distraction begins. Lower-cased and tag-stripped before comparison, and
	 * matched as a substring because the trailing punctuation is not worth depending on.
	 */
	static final String DISTRACTION_MESSAGE = "you notice an urchin distract a wealthy citizen";

	/**
	 * Printed when you pickpocket into a distraction you were not present to see start - the game's
	 * penalty for hopping in late. Useless for looting, but it does tell us the world is mid-cycle.
	 * <p>
	 * The game has at least two wordings, "hands are sweaty" and "hands are <b>very</b> sweaty",
	 * only the first of which the wiki documents. Matching from "sweaty" onwards covers both and
	 * survives any further intensifier being inserted before it.
	 */
	static final String LATE_ARRIVAL_MESSAGE = "sweaty and keep dropping";

	private static final String WEALTHY_CITIZEN = "Wealthy citizen";

	private static final long REFRESH_PERIOD_MS = 500L;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private VarlamoreDistractionConfig config;

	@Inject
	private Notifier notifier;

	/**
	 * Guards {@link #tracker}. Distractions are recorded from the client thread while the refresh
	 * task reads snapshots from an executor thread, so the two genuinely overlap.
	 */
	private final Object trackerLock = new Object();
	private final DistractionTracker tracker = new DistractionTracker();

	/** Wealthy citizens currently in the scene, maintained from spawn/despawn rather than by scanning. */
	private final Set<NPC> citizens = new HashSet<>();
	/** Of those, the ones that were distracted as of last tick. */
	private final Set<NPC> distracted = new HashSet<>();
	/** Citizens we have seen idle at least once, so a later transition is a start we witnessed. */
	private final Set<NPC> seenIdle = new HashSet<>();

	/** Last rendered state per world, so a notification fires on the crossing and not every tick. */
	private final Map<Integer, DistractionState> lastStates = new HashMap<>();

	private VarlamoreDistractionPanel panel;
	private NavigationButton navButton;
	private VarlamoreDistractionOverlay overlay;
	private ScheduledFuture<?> refreshTask;

	/** Cached so the refresh task never touches the client from another thread. */
	private volatile int currentWorld;

	@Provides
	VarlamoreDistractionConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(VarlamoreDistractionConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new VarlamoreDistractionPanel(config);

		final BufferedImage icon = ImageUtil.loadImageResource(VarlamoreDistractionPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Varlamore distractions")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlay = new VarlamoreDistractionOverlay(this, config);
		overlayManager.add(overlay);

		refreshTask = executor.scheduleAtFixedRate(
			this::refresh, 0L, REFRESH_PERIOD_MS, TimeUnit.MILLISECONDS);
	}

	@Override
	protected void shutDown()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(true);
			refreshTask = null;
		}

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		if (overlay != null)
		{
			overlayManager.remove(overlay);
			overlay = null;
		}

		panel = null;

		synchronized (trackerLock)
		{
			tracker.clear();
		}

		resetSceneState();
		lastStates.clear();
		currentWorld = 0;
	}

	// --- detection ------------------------------------------------------------------------------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		final String message = event.getMessage();
		final long now = System.currentTimeMillis();

		if (isDistractionMessage(message))
		{
			recordExact(now, "chat");
		}
		else if (isLateArrivalMessage(message) && config.seedApproximate())
		{
			// We know a distraction is running but not when it started - split the difference.
			recordApproximate(now - halfDurationMillis(), "sweaty-hands");
		}
	}

	/** Package-private and static so the wording can be tested without a client. */
	static boolean isDistractionMessage(String rawMessage)
	{
		return normalise(rawMessage).contains(DISTRACTION_MESSAGE);
	}

	static boolean isLateArrivalMessage(String rawMessage)
	{
		return normalise(rawMessage).contains(LATE_ARRIVAL_MESSAGE);
	}

	private static String normalise(String rawMessage)
	{
		// Game messages carry colour tags - the late-arrival one arrives as <col=ff3045>... - and
		// non-breaking spaces turn up in places plain trimming will not catch.
		return Text.removeTags(rawMessage).replace('\u00A0', ' ').toLowerCase(Locale.ROOT);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		final NPC npc = event.getNpc();
		if (WEALTHY_CITIZEN.equals(npc.getName()))
		{
			citizens.add(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		final NPC npc = event.getNpc();
		citizens.remove(npc);
		distracted.remove(npc);
		seenIdle.remove(npc);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		trackCitizens();
	}

	/**
	 * Watches the small set of tracked citizens for distraction transitions. This is insurance on the
	 * chat message above, and the only way to learn anything about a world we arrived at mid-cycle.
	 */
	private void trackCitizens()
	{
		if (citizens.isEmpty())
		{
			return;
		}

		final long now = System.currentTimeMillis();
		final boolean seed = config.seedApproximate();

		for (NPC npc : citizens)
		{
			final boolean isDistracted = isDistracted(npc);
			final boolean wasDistracted = distracted.contains(npc);

			if (isDistracted && !wasDistracted)
			{
				if (seenIdle.contains(npc))
				{
					// We were already watching this citizen when it became distracted, so this is
					// the start instant itself - as precise as the chat message. In practice the
					// interacting flag lands a tick or two after the chat line, which is why the
					// tracker keeps the earliest reading of a given distraction rather than the
					// latest.
					recordExact(now, "npc-start");
				}
				else if (seed)
				{
					// It was already distracted the first time we saw it. All we know is that it
					// started somewhere in the preceding distraction window.
					recordApproximate(now - halfDurationMillis(), "npc-in-progress");
				}
				distracted.add(npc);
			}
			else if (!isDistracted)
			{
				if (wasDistracted)
				{
					distracted.remove(npc);
					if (seed)
					{
						// Watching it end pins the start far better than watching it run, so this
						// gets a higher trust tier than the other estimates rather than relying on
						// it happening to produce the earliest stamp.
						record(now - config.distractionDuration() * 1000L,
							DistractionSource.ESTIMATED_FROM_END, "npc-end");
					}
				}
				seenIdle.add(npc);
			}
		}
	}

	private static boolean isDistracted(NPC npc)
	{
		if (!npc.isInteracting())
		{
			return false;
		}

		// The urchin has no combat level, which is what separates a distraction from ordinary
		// citizen-on-citizen idle interaction.
		final Actor target = npc.getInteracting();
		return target != null && target.getCombatLevel() == 0;
	}

	private void recordExact(long stampMillis, String via)
	{
		record(stampMillis, DistractionSource.EXACT_LOCAL, via);
	}

	private void recordApproximate(long stampMillis, String via)
	{
		record(stampMillis, DistractionSource.APPROXIMATE_LOCAL, via);
	}

	/**
	 * Returns true only when this reading actually changed what we hold. All three urchins fire at
	 * once and each citizen reports separately, so most readings in a cycle are duplicates of one
	 * already recorded - reporting or logging every one of them would be noise.
	 */
	private boolean record(long stampMillis, DistractionSource source, String via)
	{
		final int world = client.getWorld();
		if (world <= 0)
		{
			return false;
		}

		final boolean applied;
		synchronized (trackerLock)
		{
			applied = tracker.record(world, stampMillis, source);
		}

		if (applied)
		{
			log.debug("Distraction on world {} via {} in region {}", world, via, currentRegion());
		}
		else
		{
			log.debug("Ignored {} reading for world {} - already hold a better one", via, world);
		}

		return applied;
	}

	private long halfDurationMillis()
	{
		return config.distractionDuration() * 1000L / 2L;
	}

	private int currentRegion()
	{
		final Player local = client.getLocalPlayer();
		return local == null ? -1 : local.getWorldLocation().getRegionID();
	}

	// --- world state ----------------------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();

		if (state == GameState.LOGGED_IN)
		{
			// There is no WorldChanged event; re-reading the world on every LOGGED_IN is the
			// pattern the built-in world hopper uses, and it covers first login too.
			final int world = client.getWorld();
			if (world != currentWorld)
			{
				currentWorld = world;
				resetSceneState();
			}
		}
		else if (state == GameState.HOPPING || state == GameState.LOADING
			|| state == GameState.LOGIN_SCREEN)
		{
			// NPC references do not survive a scene reload, and despawn events are not guaranteed.
			resetSceneState();
		}
	}

	private void resetSceneState()
	{
		citizens.clear();
		distracted.clear();
		seenIdle.clear();
	}

	// --- refresh --------------------------------------------------------------------------------

	private void refresh()
	{
		// scheduleAtFixedRate silently cancels the task if it ever throws, which would freeze the
		// panel with no visible cause. Swallow and log instead.
		try
		{
			final long now = System.currentTimeMillis();

			final List<WorldTimer> rows;
			synchronized (trackerLock)
			{
				rows = tracker.snapshot(now, thresholds());
			}

			notifyApproaching(rows);

			final VarlamoreDistractionPanel current = panel;
			if (current != null)
			{
				final int world = currentWorld;
				SwingUtilities.invokeLater(() -> current.update(rows, world));
			}
		}
		catch (Exception e)
		{
			log.debug("Refresh failed", e);
		}
	}

	/**
	 * Fires once as a world crosses into the approaching band, never repeatedly while it sits
	 * there. The world you are standing on is skipped - you can already see it, and telling you to
	 * hop to where you are is noise.
	 */
	private void notifyApproaching(List<WorldTimer> rows)
	{
		final Notification notification = config.approachingNotification();
		final int here = currentWorld;

		final Set<Integer> live = new HashSet<>();
		for (WorldTimer row : rows)
		{
			live.add(row.getWorld());

			final DistractionState previous = lastStates.put(row.getWorld(), row.getState());
			final boolean crossedIn = row.getState() == DistractionState.APPROACHING
				&& previous != DistractionState.APPROACHING;

			if (crossedIn && row.getWorld() != here && notification.isEnabled())
			{
				notifier.notify(notification, "World " + row.getWorld() + " is due a distraction.");
			}
		}

		// Forget worlds that aged out, so returning to one can alert again.
		lastStates.keySet().retainAll(live);
	}

	private DistractionTracker.Thresholds thresholds()
	{
		return new DistractionTracker.Thresholds(
			config.distractionDuration(),
			config.approachingAt(),
			config.imminentAt(),
			config.missedAt(),
			config.retentionSeconds());
	}

	// --- accessors for the panel and overlay ----------------------------------------------------

	int getCurrentWorld()
	{
		return currentWorld;
	}

	@Nullable
	WorldTimer currentWorldTimer()
	{
		final int world = currentWorld;
		if (world <= 0)
		{
			return null;
		}

		synchronized (trackerLock)
		{
			return tracker.forWorld(world, System.currentTimeMillis(), thresholds());
		}
	}

	OptionalInt bestTarget()
	{
		synchronized (trackerLock)
		{
			return tracker.bestTarget(System.currentTimeMillis(), thresholds());
		}
	}

	List<WorldTimer> currentRows()
	{
		synchronized (trackerLock)
		{
			return new ArrayList<>(tracker.snapshot(System.currentTimeMillis(), thresholds()));
		}
	}

	// --- shared formatting ----------------------------------------------------------------------

	static Color colourFor(DistractionState state, VarlamoreDistractionConfig config)
	{
		switch (state)
		{
			case ACTIVE:
				return config.activeColor();
			case APPROACHING:
				return config.approachingColor();
			case IMMINENT:
				return config.imminentColor();
			case MISSED:
				return config.missedColor();
			case FRESH:
			default:
				return config.freshColor();
		}
	}

	/**
	 * What the right-hand side of a row says.
	 * <p>
	 * While the distraction is running this counts <em>down</em> to the moment it ends, because
	 * that moment is fixed and knowable. Afterwards it counts <em>up</em>, because the only thing
	 * left to say is how long ago it was - the next one is random across 84-99s and no countdown
	 * would be honest. Frozen at "N+" once the distraction has certainly fired unseen, and prefixed
	 * with ~ when the start was inferred rather than witnessed.
	 */
	static String formatElapsed(WorldTimer row, VarlamoreDistractionConfig config)
	{
		final String value;
		switch (row.getState())
		{
			case ACTIVE:
				value = Math.max(0L, config.distractionDuration() - row.getElapsedSeconds()) + "s left";
				break;
			case MISSED:
				value = config.missedAt() + "+";
				break;
			default:
				value = row.getElapsedSeconds() + "s";
				break;
		}

		return row.isApproximate() ? "~" + value : value;
	}
