package com.varlamoredistraction;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.OptionalInt;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Compact in-game readout: the world you are standing on, and the one worth hopping to.
 * <p>
 * Off by default. Other Varlamore thieving plugins draw their own single-world timer, and two
 * overlays counting the same seconds is worse than one.
 */
class VarlamoreDistractionOverlay extends OverlayPanel
{
	private final VarlamoreDistractionPlugin plugin;
	private final VarlamoreDistractionConfig config;

	VarlamoreDistractionOverlay(VarlamoreDistractionPlugin plugin, VarlamoreDistractionConfig config)
	{
		super(plugin);

		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(140, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		final WorldTimer here = plugin.currentWorldTimer();
		final OptionalInt best = plugin.bestTarget();

		if (here == null && !best.isPresent())
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Distraction")
			.color(Color.WHITE)
			.build());

		if (here != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("This world")
				.right(VarlamoreDistractionPlugin.formatElapsed(here, config))
				.rightColor(VarlamoreDistractionPlugin.colourFor(here.getState(), config))
				.build());
		}

		if (best.isPresent() && (here == null || best.getAsInt() != plugin.getCurrentWorld()))
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Hop to")
				.right("W" + best.getAsInt())
				.build());
		}

		return super.render(graphics);
	}
}
